// Parse the OpenAI response and validate the JSON structure
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    // Get the response text from OpenAI
    let responseText = item.json.message?.content || item.json.text || item.json.output || '';

    // Clean up the response - remove markdown code blocks if present
    responseText = responseText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

    // Parse the JSON
    let extracted;
    try {
      extracted = JSON.parse(responseText);
    } catch (parseError) {
      // If parsing fails, create a default structure
      extracted = {
        category: 'Other',
        vendor: null,
        document_date: null,
        total_amount: 0,
        currency: null,
        line_items: [],
        confidence: 0.1,
        missing_fields: ['vendor', 'document_date', 'total_amount'],
        notes: 'Failed to parse AI response: ' + parseError.message
      };
    }

    // Validate and normalize the extracted data
    const normalized = {
      category: ['Invoice', 'Receipt', 'Contract', 'Other'].includes(extracted.category) ? extracted.category : 'Other',
      vendor: extracted.vendor || null,
      document_date: extracted.document_date || null,
      total_amount: typeof extracted.total_amount === 'number' ? extracted.total_amount : parseFloat(extracted.total_amount) || 0,
      currency: extracted.currency || null,
      line_items: Array.isArray(extracted.line_items) ? extracted.line_items : [],
      confidence: typeof extracted.confidence === 'number' ? Math.min(1, Math.max(0, extracted.confidence)) : 0.5,
      missing_fields: Array.isArray(extracted.missing_fields) ? extracted.missing_fields : [],
      notes: extracted.notes || ''
    };

    // Determine required fields based on category
    let requiredFields = [];
    if (normalized.category === 'Invoice' || normalized.category === 'Receipt') {
      requiredFields = ['vendor', 'document_date', 'total_amount'];
    } else if (normalized.category === 'Contract') {
      requiredFields = ['vendor', 'document_date'];
    }

    // Check for missing required fields
    const actualMissingFields = [];
    for (const field of requiredFields) {
      if (normalized[field] === null || normalized[field] === undefined || normalized[field] === '' || (field === 'total_amount' && normalized[field] === 0)) {
        if (!actualMissingFields.includes(field)) {
          actualMissingFields.push(field);
        }
      }
    }

    // Merge with AI-reported missing fields
    for (const field of normalized.missing_fields) {
      if (!actualMissingFields.includes(field)) {
        actualMissingFields.push(field);
      }
    }
    normalized.missing_fields = actualMissingFields;

    // Carry forward all previous data
    results.push({
      json: {
        ...item.json,
        extracted: normalized,
        extractionRaw: responseText
      },
      binary: item.binary
    });

  } catch (error) {
    // On any error, create error result
    results.push({
      json: {
        ...item.json,
        extracted: {
          category: 'Other',
          vendor: null,
          document_date: null,
          total_amount: 0,
          currency: null,
          line_items: [],
          confidence: 0,
          missing_fields: ['vendor', 'document_date', 'total_amount'],
          notes: 'Extraction error: ' + error.message
        },
        extractionError: error.message
      },
      binary: item.binary
    });
  }
}

return results;

// Determine the document year and build the folder path/filename
const items = $input.all();
const results = [];

for (const item of items) {
  const extracted = item.json.extracted;
  const originalFilename = item.json.originalFilename || 'document';

  // Determine year from document_date or email received date
  let year;
  if (extracted.document_date) {
    year = extracted.document_date.substring(0, 4);
  } else {
    const receivedDate = new Date(item.json.emailReceivedDate || new Date());
    year = receivedDate.getFullYear().toString();
  }

  // Build the filename: <YYYY-MM-DD>_<Category>_<Vendor>_<Total>_<OriginalFilename>
  const dateStr = extracted.document_date || new Date().toISOString().substring(0, 10);
  const category = extracted.category || 'Other';
  const vendor = extracted.vendor || 'Unknown';
  const total = extracted.total_amount > 0 ? extracted.total_amount.toFixed(2) : '0.00';

  // Sanitize for filename (remove special characters)
  const sanitize = (str) => str.replace(/[<>:"/\\|?*]/g, '_').replace(/\s+/g, '_').substring(0, 50);

  // Get original extension
  const extMatch = originalFilename.match(/\.[^.]+$/);
  const extension = extMatch ? extMatch[0] : '';
  const baseName = originalFilename.replace(/\.[^.]+$/, '');

  const newFilename = `${dateStr}_${sanitize(category)}_${sanitize(vendor)}_${total}_${sanitize(baseName)}${extension}`;

  // Determine status based on confidence and missing fields
  const threshold = item.json.config_confidenceThreshold || 0.7;
  const hasMissingRequired = extracted.missing_fields.length > 0;
  const isLowConfidence = extracted.confidence < threshold;
  const isOtherCategory = extracted.category === 'Other';
  const hasError = item.json.extractionError ? true : false;

  let status;
  let needsNotification = false;
  let notificationReason = [];

  if (hasError) {
    status = 'Error';
    needsNotification = true;
    notificationReason.push('Extraction error occurred');
  } else if (isLowConfidence || isOtherCategory || hasMissingRequired) {
    status = 'Needs Review';
    needsNotification = true;
    if (isLowConfidence) notificationReason.push(`Low confidence (${(extracted.confidence * 100).toFixed(0)}%)`);
    if (isOtherCategory) notificationReason.push('Categorized as Other');
    if (hasMissingRequired) notificationReason.push(`Missing fields: ${extracted.missing_fields.join(', ')}`);
  } else {
    status = 'Processed';
  }

  results.push({
    json: {
      ...item.json,
      year: year,
      category: category,
      newFilename: newFilename,
      status: status,
      needsNotification: needsNotification,
      notificationReason: notificationReason.join('; ')
    },
    binary: item.binary
  });
}

return results;

// Build the row for Google Sheets logging
const items = $input.all();
const results = [];

for (const item of items) {
  // Get all the data we need
  const prevData = $('Determine Year and Status').item.json;
  const extracted = prevData.extracted;
  const driveFile = item.json;

  // Build the Drive URL
  const driveUrl = driveFile.webViewLink || driveFile.webContentLink || 
    (driveFile.id ? `https://drive.google.com/file/d/${driveFile.id}/view` : '');

  // Format the log row
  const logRow = {
    received_timestamp: new Date(prevData.emailReceivedDate || new Date()).toISOString(),
    email_subject: prevData.emailSubject || '',
    from_address: prevData.emailFrom || '',
    original_filename: prevData.originalFilename || '',
    category: extracted.category || 'Other',
    vendor: extracted.vendor || '',
    document_date: extracted.document_date || '',
    total_amount: extracted.total_amount || 0,
    currency: extracted.currency || '',
    line_items_count: extracted.line_items?.length || 0,
    confidence: extracted.confidence || 0,
    missing_fields: extracted.missing_fields?.join(', ') || '',
    drive_file_url: driveUrl,
    status: prevData.status || 'Unknown',
    notes: extracted.notes || '',
    dedupe_key: prevData.dedupeKey || ''
  };

  results.push({
    json: {
      ...prevData,
      logRow: logRow,
      driveUrl: driveUrl,
      driveFileId: driveFile.id
    },
    binary: item.binary
  });
}

return results;

